<template><el-drawer :visible.sync="innerVisible" size="620px" append-to-body @close="$emit('update:visible',false)"><div slot="title" class="todo-drawer-title"><span>TODO PROFILE</span><strong>{{ detail.title || '待办详情' }}</strong></div><div class="todo-detail"><el-descriptions :column="2" border><el-descriptions-item label="待办编号">{{ value('todoNo','todo_no') }}</el-descriptions-item><el-descriptions-item label="状态">{{ value('status') }}</el-descriptions-item><el-descriptions-item label="优先级">{{ value('priority') }}</el-descriptions-item><el-descriptions-item label="SLA">{{ value('slaStatus','sla_status') }}</el-descriptions-item><el-descriptions-item label="负责人">{{ value('ownerName','owner_name') || value('ownerId','owner_id') }}</el-descriptions-item><el-descriptions-item label="截止时间">{{ value('dueAt','due_at') || '-' }}</el-descriptions-item></el-descriptions><todo-relation-panel :detail="detail" /></div></el-drawer></template>
<script>import TodoRelationPanel from './TodoRelationPanel'; export default { name:'TodoDetailDrawer',components:{TodoRelationPanel},props:{visible:Boolean,detail:{type:Object,default:()=>({})}},computed:{innerVisible:{get(){return this.visible},set(v){this.$emit('update:visible',v)}}},methods:{value(...keys){for(const key of keys)if(this.detail[key]!==undefined&&this.detail[key]!==null)return this.detail[key];return '-'}} }</script>
<style scoped>.todo-drawer-title span,.todo-drawer-title strong{display:block}.todo-drawer-title span{font-size:11px;color:#64748b}.todo-drawer-title strong{font-size:18px;color:#0f172a}.todo-detail{display:grid;gap:16px;padding:18px}</style>
